import { loghubLog, LogLevel } from './index.js';

export interface LoghubLoggerOptions {
  service: string;
  app: string;
  /** Defaults to process.env.NODE_ENV ?? 'prod' */
  env?: string;
}

const LEVEL_MAP: Record<string, LogLevel> = {
  log: 'info',
  verbose: 'debug',
  debug: 'debug',
  warn: 'warn',
  error: 'error',
  fatal: 'error',
};

/**
 * NestJS-compatible logger that forwards all logs to Grafana via loghub.
 * Implements the LoggerService duck-type interface — no @nestjs/common dependency needed.
 *
 * Usage in main.ts:
 *   import { LoghubLogger } from '@geos/loghub-client';
 *   const app = await NestFactory.create(AppModule, {
 *     logger: new LoghubLogger({ service: 'my-api', app: 'my-app' }),
 *   });
 */
export class LoghubLogger {
  private readonly service: string;
  private readonly app: string;
  private readonly env: string;

  constructor(options: LoghubLoggerOptions) {
    this.service = options.service;
    this.app = options.app;
    this.env = options.env ?? process.env.NODE_ENV ?? 'prod';
  }

  private send(nestLevel: string, message: any, ...optionalParams: any[]): void {
    // NestJS passes context as the last string param
    const context =
      typeof optionalParams[optionalParams.length - 1] === 'string'
        ? (optionalParams[optionalParams.length - 1] as string)
        : undefined;

    const level = LEVEL_MAP[nestLevel] ?? 'info';
    const msg = typeof message === 'string' ? message : JSON.stringify(message);

    // Print to stdout so Railway/console logs still work
    const prefix = context ? `[${context}]` : '';
    if (level === 'error') {
      console.error(`${prefix} ${msg}`);
    } else if (level === 'warn') {
      console.warn(`${prefix} ${msg}`);
    } else {
      console.log(`${prefix} ${msg}`);
    }

    // Forward to Grafana via loghub (fire-and-forget)
    loghubLog({
      service: this.service,
      app: this.app,
      env: this.env,
      level,
      message: msg,
      ...(context && { attrs: { context } }),
    });
  }

  log(message: any, ...optionalParams: any[]): void {
    this.send('log', message, ...optionalParams);
  }

  error(message: any, ...optionalParams: any[]): void {
    this.send('error', message, ...optionalParams);
  }

  warn(message: any, ...optionalParams: any[]): void {
    this.send('warn', message, ...optionalParams);
  }

  debug(message: any, ...optionalParams: any[]): void {
    this.send('debug', message, ...optionalParams);
  }

  verbose(message: any, ...optionalParams: any[]): void {
    this.send('verbose', message, ...optionalParams);
  }

  fatal(message: any, ...optionalParams: any[]): void {
    this.send('fatal', message, ...optionalParams);
  }
}
